interface TreeTeardown { kind: "retire" | "close"; settled: Promise<void>; }
// field
private readonly closingTrees = new Map<IssueKey, TreeTeardown>();

async retireTreeProcesses(treeKey: IssueKey): Promise<void> {
  const inFlight = this.closingTrees.get(treeKey);
  if (inFlight) { await inFlight.settled; return; }
  const retiring = this.retireTreeProcessesLocked(treeKey).finally(() => this.closingTrees.delete(treeKey));
  this.closingTrees.set(treeKey, { kind: "retire", settled: retiring.then(() => {}, () => {}) });
  await retiring;
}

async closeTree(treeKey: IssueKey): Promise<void> {
  for (;;) {
    const inFlight = this.closingTrees.get(treeKey);
    if (!inFlight) break;
    await inFlight.settled;            // the finally above has already deleted the entry
    if (inFlight.kind === "close") return;
  }
  const closing = this.closeTreeLocked(treeKey).finally(() => this.closingTrees.delete(treeKey));
  this.closingTrees.set(treeKey, { kind: "close", settled: closing.then(() => {}, () => {}) });
  const releasedSlot = await closing;
  if (releasedSlot) await this.beginPromotionSweep();
}

private async closeTreeLocked(treeKey: IssueKey): Promise<boolean> {
  const tree = this.requireTree(treeKey);
  if (tree.status !== "lingering") { tree.status = "lingering"; tree.lingerUntil = new Date(this.deps.now()).toISOString(); await this.persist(); }
  try {
    await this.retireTreeProcessesLocked(treeKey);
  } catch (error) {
    // Today's contract: a failed close leaves the tree lingering with an immediately-expired lingerUntil so the sweep retries.
    tree.status = "lingering";
    tree.lingerUntil = new Date(this.deps.now()).toISOString();
    await this.persist();
    throw error;
  }
  await this.removeTreeWorkspaces(treeKey, tree);
  tree.status = "closed";
  delete tree.lingerUntil;
  delete tree.resumeSessionFile;   // the reopen window ends with the record
  /* :2363-2370 writeStatus + slot release unchanged */
  this.clearTreePhases(treeKey);
  await this.persist();
  this.workerAdmission.promoteWorkerQueue();
  return releasedSlot;
}

private async retireTreeProcessesLocked(treeKey: IssueKey): Promise<void> {
  const tree = this.requireTree(treeKey);
  this.cancelRootRegistrationDeadline(treeKey);
  let anyFailed = false;
  let rootOutcome = "none";
  if (tree.locator) {
    /* :2259-2277 verbatim (revoke architect claim, probeTree, stopProcessSerialized with skipGraceful/refuseKill) */
    try {
      /* probe + stop */
      if (rootLocator.ompSessionFile !== undefined) tree.resumeSessionFile = rootLocator.ompSessionFile;
      if (tree.locator === rootLocator) delete tree.locator;
      rootOutcome = "stopped";
    } catch (error) {
      anyFailed = true;
      console.error(`[legion] root process failed to stop while retiring the processes of ${treeKey}:`, error);
    }
  }
  /* :2286-2346 the worker fixed-point loop verbatim, counting stoppedWorkers; the failure line reads `worker ${token} failed to stop while retiring the processes of ${treeKey}` */
  // Every claim under the tree that has no locator (the architect's, a queued never-launched worker's, a retired idle worker's): a failed stop above keeps its locator, so it is naturally skipped here.
  for (const [token, claim] of Object.entries(this.deps.state.roles)) {
    if ("issue" in claim && claim.locator === undefined && this.rootForIssue(claim.issue) === treeKey) {
      await this.workerAdmission.mutateClaim(token, async () => { this.cancelBootWatchdog(token); this.revokeRoleClaim(claim); delete this.deps.state.roles[token]; });
    }
  }
  this.clearTreePhases(treeKey);
  await this.workerAdmission.pruneQueueForTree(treeKey);
  for (const [key, capability] of Object.entries(this.deps.state.spawnCapabilities)) if (capability.tree === treeKey) delete this.deps.state.spawnCapabilities[key];
  await this.persist();
  if (anyFailed) throw new StopFailed(treeKey, `Legion tree ${treeKey} has a process that could not be stopped`);
  if (rootOutcome !== "none" || stoppedWorkers > 0 || removedClaims > 0) {
    console.error(`[legion] retired the processes of ${tree.status} tree ${treeKey}: root ${rootOutcome}, ${stoppedWorkers} worker(s) stopped, ${removedClaims} claim(s) removed; the root's session file is kept for a reopen`);
  }
}
