async beginLinger(treeKey: IssueKey): Promise<void> {
  const tree = this.requireTree(treeKey);
  this.cancelRootRegistrationDeadline(treeKey);
  tree.status = "lingering";
  tree.lingerUntil = new Date(this.deps.now() + this.deps.config.lingerHours * HOUR_MS).toISOString();
  this.clearTreePhases(treeKey);
  await this.releaseSlot(treeKey);
  await this.persist();
  // After the durable decision, never inside it: a stop can take tree_stop_timeout_seconds and can fail, and a throw here exits the daemon (events.ts `fatal`).
  void this.retireTreeProcesses(treeKey).catch((error) => {
    console.error(`[legion] retiring the processes of lingering tree ${treeKey} failed after linger; its surviving locators and claims are kept and the linger sweep retries:`, error);
  });
}

async retireLingeringTrees(): Promise<void> {
  const targets = Object.values(this.deps.state.trees).filter((tree) => tree.status === "lingering" && this.treeRecordsProcesses(tree.root));
  if (targets.length === 0) return;
  console.error(`[legion] retiring the processes of ${targets.length} lingering tree(s) that still record a locator or a role claim`);
  await Promise.allSettled(targets.map((tree) => this.retireTreeProcesses(tree.root).catch((error) => {
    console.error(`[legion] retiring the processes of lingering tree ${tree.root} failed; its surviving locators and claims are kept for the next sweep tick:`, error);
  })));
}

private treeRecordsProcesses(treeKey: IssueKey): boolean {
  if (this.deps.state.trees[treeKey]?.locator !== undefined) return true;
  return Object.values(this.deps.state.roles).some((claim) => "issue" in claim && this.rootForIssue(claim.issue) === treeKey);
}

async reportRootExit(treeKey: IssueKey): Promise<void> {
  const tree = this.requireTree(treeKey);
  const closing = this.closingTrees.has(treeKey);
  await this.recordRootExit(treeKey, tree);
  if (!closing) {
    // The root is gone (it told us); what is left are its workers. Retire them, never close: the tree keeps its linger window and the sweep closes it at lingerUntil.
    void this.retireTreeProcesses(treeKey).catch((error) => {
      console.error(`[legion] background retire for ${treeKey} failed after a root self-report:`, error);
    });
  }
}
